function fallbackActions(title: string): FarmCard["actions"] { if (title === "Choose the source for a new farm version") return [backAction, localAction("review-json", "Review farm JSON"), localAction("review-demo", "Review demo load")]; if (title === "Paste farm JSON") return [backAction, localAction("download-schema", "Download full-schema farm"), localAction("review-farm", "Review parsed farm")]; if (title === "Review farm import") return [backAction, localAction("edit-json", "Edit JSON"), serverAction("confirm-import", "Confirm atomic import")]; if (title === "Load synthetic demo") return [backAction, serverAction("confirm-demo", "Confirm atomic demo load", false)]; if (title === "Import a farm record") return [backAction, localAction("manual", "Manual instead"), serverAction("upload-accounting", "Upload accounting candidate", false), serverAction("extract-document", "Submit for AI extraction", false)]; if (title === "Create an unverified candidate") return [backAction, serverAction("create-candidate", "Create review candidate", false)]; return [backAction]; }
function useLiveFooterActions(card: FarmCard, signature: string): FarmCard { const [live, setLive] = useState(card); useEffect(() => { const footer = document.querySelector<HTMLElement>(".integrated-records > .ir-actions"); if (!footer) { setLive(card); return; } const sync = () => { const buttons = Array.from(footer.querySelectorAll<HTMLButtonElement>("button")).filter(button => button.getClientRects().length > 0), actions = buttons.map((button, index) => { const label = button.textContent?.replace(/\s+/g, " ").trim() || `Action ${index + 1}`, declared = card.actions.find(action => action.label === label); return { ...(declared || localAction(`visible-${index}`, label)), eligible: !button.disabled, ...(!button.disabled ? { disabledReason: undefined } : { disabledReason: declared?.disabledReason || "Complete the required fields or wait for the current request." }) }; }); setLive({ ...card, actions }); }; sync(); const observer = new MutationObserver(sync); observer.observe(footer, { subtree: true, childList: true, attributes: true, characterData: true, attributeFilter: ["disabled"] }); return () => observer.disconnect(); }, [signature]); return live; }
